package com.library.server.controller; import com.library.common.annotation.RequireRole; import com.library.common.constant.RoleConstant; import com.library.common.model.*; import com.library.pojo.dto.BookQuery; import com.library.pojo.entity.Book; import com.library.pojo.vo.BookVO; import com.library.server.service.BookService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List; import java.util.Map;
@RestController @RequestMapping("/api/books") public class BookController { private final BookService service; public BookController(BookService service){this.service=service;} @GetMapping public ApiResult<PageResult<BookVO>> page(BookQuery q){return ApiResult.success(service.page(q));} @GetMapping("/{id}") public ApiResult<Book> get(@PathVariable Long id){return ApiResult.success(service.get(id));} @PostMapping @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> save(@Valid @RequestBody Book x){service.save(x);return ApiResult.success();} @PutMapping @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> update(@Valid @RequestBody Book x){service.update(x);return ApiResult.success();} @DeleteMapping("/{id}") @RequireRole(RoleConstant.ADMIN) public ApiResult<Void> delete(@PathVariable Long id){service.delete(id);return ApiResult.success();} @GetMapping("/stats") @RequireRole({RoleConstant.ADMIN,RoleConstant.READER}) public ApiResult<List<Map<String,Object>>> stats(){return ApiResult.success(service.stats());} }
